[asy] int triplepts(real x1, real y1, real x2, real y2, real x3, real y3) {
  real x, y, len12, len13, len23;

  x = (x1+x2+x3)/3;
  y = (y1+y2+y3)/3;

  len12 = sqrt((x2-x1)^2+(y2-y1)^2);
  len13 = sqrt((x3-x1)^2+(y3-y1)^2);
  len23 = sqrt((x3-x2)^2+(y3-y2)^2);

  if (len12+len13>len23 && len12+len13<2*len23) return true;
  return false;
}

real triArea(real x1, real y1, real x2, real y2, real x3, real y3, real x4) {
